// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 arg) internal {
        uint256 beforeMinSum;
        try c.MinSum() returns (uint256 __r) { beforeMinSum = __r; } catch { return; }
        bool reverted;
        try c.SetMinSum(arg) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterMinSum;
        try c.MinSum() returns (uint256 __r) { afterMinSum = __r; } catch { return; }
        assertTrue((!reverted || afterMinSum == beforeMinSum) &&
            (reverted && afterMinSum == beforeMinSum || !reverted && afterMinSum == arg));
    }

    function testFuzz_run(uint256 arg) public {
        _run(arg);
    }

    receive() external payable {}
}
